fn tab_items() -> Vec<Tab> {
    vec![
        Tab::new("General"),
        Tab::new("Appearance"),
        Tab::new("Agents").badge(3),
        Tab::new("Connections"),
        Tab::new("Privacy"),
        Tab::new("Advanced"),
    ]
}

fn row(area: Rect, y: u16, height: u16) -> Rect {
    Rect {
        y: area.y.saturating_add(y),
        height,
        ..area
    }
    .intersection(area)
}
